insert into audit_log (
    trace_id, actor_type, actor_service, action, resource_type, resource_id,
    scope_type, scope_id, result, after_json, reason
) values (
    #{traceId}, 'SERVICE', #{actorService}, #{action}, #{resourceType}, #{resourceId},
    #{scopeType}, null, #{result}, cast(#{afterJson} as jsonb), #{reason}
)
